const listUpcomingEventDates = `-- name: ListUpcomingEventDates :many
SELECT id, event_id, event_date, start_time, end_time, created_at, updated_at
FROM agenda_event_dates
WHERE event_id = $1
  AND (
      event_date > $2::date
      OR (event_date = $2::date
          AND (end_time IS NULL OR end_time::time >= $3::time))
  )
ORDER BY event_date, start_time NULLS FIRST, id
`

type ListUpcomingEventDatesParams struct {
	EventID pgtype.UUID
	Today   pgtype.Date
	NowTime pgtype.Time
}

// Público: solo las fechas próximas del evento (regla R4-2). La primera es
// "la próxima fecha" (FR-004).
func (q *Queries) ListUpcomingEventDates(ctx context.Context, arg ListUpcomingEventDatesParams) ([]AgendaEventDate, error) {
	rows, err := q.db.Query(ctx, listUpcomingEventDates, arg.EventID, arg.Today, arg.NowTime)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []AgendaEventDate
	for rows.Next() {
		var i AgendaEventDate
		if err := rows.Scan(
			&i.ID,
			&i.EventID,
			&i.EventDate,
			&i.StartTime,
			&i.EndTime,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listUpcomingEvents = `-- name: ListUpcomingEvents :many
WITH upcoming AS (
    SELECT e.id AS event_id, min(d.event_date)::date AS next_date
    FROM agenda_events e
    JOIN agenda_event_dates d ON d.event_id = e.id
    WHERE e.publication_state = 'published'
      AND (
          d.event_date > $2::date
          OR (d.event_date = $2::date
              AND (d.end_time IS NULL OR d.end_time::time >= $3::time))
      )
    GROUP BY e.id
)
SELECT e.id, e.title_es, e.title_en, e.frequency_es, e.frequency_en,
       e.detail_es, e.detail_en, e.place_es, e.place_en, e.map_url,
       e.organizer_es, e.organizer_en, e.category_id, e.image_file,
       e.image_alt_es, e.image_alt_en, e.publication_state,
       e.created_at, e.updated_at, u.next_date
FROM agenda_events e
JOIN upcoming u ON u.event_id = e.id
ORDER BY u.next_date, e.title_es, e.id
LIMIT $1
`

type ListUpcomingEventsParams struct {
	Lim     int32
	Today   pgtype.Date
	NowTime pgtype.Time
}

type ListUpcomingEventsRow struct {
	ID               pgtype.UUID
	TitleEs          string
	TitleEn          pgtype.Text
	FrequencyEs      pgtype.Text
	FrequencyEn      pgtype.Text
	DetailEs         string
	DetailEn         pgtype.Text
	PlaceEs          string
	PlaceEn          pgtype.Text
	MapUrl           pgtype.Text
	OrganizerEs      pgtype.Text
	OrganizerEn      pgtype.Text
	CategoryID       pgtype.UUID
	ImageFile        pgtype.Text
	ImageAltEs       pgtype.Text
	ImageAltEn       pgtype.Text
	PublicationState string
	CreatedAt        pgtype.Timestamptz
	UpdatedAt        pgtype.Timestamptz
	NextDate         pgtype.Date
}

// Público: `published` Y con ≥ 1 fecha próxima (R4-2). Orden por la primera
// fecha próxima con desempate estable `title_es, id` (FR-003; edge case de dos
// elementos en la misma fecha). El tope `lim` es `maxBlockItems` (RG4-8).
func (q *Queries) ListUpcomingEvents(ctx context.Context, arg ListUpcomingEventsParams) ([]ListUpcomingEventsRow, error) {
	rows, err := q.db.Query(ctx, listUpcomingEvents, arg.Lim, arg.Today, arg.NowTime)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListUpcomingEventsRow
	for rows.Next() {
		var i ListUpcomingEventsRow
		if err := rows.Scan(
			&i.ID,
			&i.TitleEs,
			&i.TitleEn,
			&i.FrequencyEs,
			&i.FrequencyEn,
			&i.DetailEs,
			&i.DetailEn,
			&i.PlaceEs,
			&i.PlaceEn,
			&i.MapUrl,
			&i.OrganizerEs,
			&i.OrganizerEn,
			&i.CategoryID,
			&i.ImageFile,
			&i.ImageAltEs,
			&i.ImageAltEn,
			&i.PublicationState,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.NextDate,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

